import { randomBytes } from 'node:crypto';
import { mkdir, readFile, rm, writeFile } from 'node:fs/promises';
import path from 'node:path';

export const STORAGE = Symbol('OBJECT_STORAGE');

/** Private object storage. Keys are generated by the server; callers never choose a path. */
export interface ObjectStorage {
  put(key: string, data: Buffer): Promise<void>;
  get(key: string): Promise<Buffer | null>;
  remove(key: string): Promise<void>;
}

export const newStorageKey = (prefix: string) => `${prefix}/${randomBytes(16).toString('hex')}`;

/**
 * Local-disk storage for development and tests. An S3-compatible adapter (MinIO/R2) is the
 * production plan and is NOT built yet; do not run production on local disk.
 */
export class LocalDiskStorage implements ObjectStorage {
  constructor(private readonly root: string) {}

  private resolve(key: string): string {
    // Keys are server-generated hex paths; still refuse anything that could leave the root.
    if (!/^[a-z0-9_-]+\/[a-f0-9]{32}$/.test(key)) throw new Error('invalid storage key');
    return path.join(this.root, key);
  }

  async put(key: string, data: Buffer): Promise<void> {
    const file = this.resolve(key);
    await mkdir(path.dirname(file), { recursive: true });
    await writeFile(file, data, { flag: 'wx' });
  }

  async get(key: string): Promise<Buffer | null> {
    try {
      return await readFile(this.resolve(key));
    } catch (e) {
      if ((e as NodeJS.ErrnoException).code === 'ENOENT') return null;
      throw e;
    }
  }

  async remove(key: string): Promise<void> {
    await rm(this.resolve(key), { force: true });
  }
}

export const defaultStorage = (): ObjectStorage => {
  if (process.env.NODE_ENV === 'production') {
    throw new Error('No production object storage is configured. Local disk storage is for development only.');
  }
  return new LocalDiskStorage(process.env.STORAGE_DIR ?? path.resolve(process.cwd(), '../../.data/uploads'));
};
